) AS (
  VALUES 
    (88::BIGINT, 'En general el curso es fácil y el no lo complica innecesariamente, los exámenes son muy parecidos a las tareas, se supone que la asistencia es obligatoria pero nunca pasa lista, lo que se presta si quiere ser autodidacta e ir solo a hacer los exámenes, todas las tareas son en grupo'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, '890da8344fe96740a2b3f7ab5fe0f03a60b6b07ce507dbaaf548c1f1e4feabdd'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Muy buen profesor, algo confuso con la teoría pero con entender los ejercicios se pasa el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '4248ddf81b76bfbcf495debd978b48b19034b05fe7b0bcd4e99416a1741f0a83'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Un buen profesor, pero sus clases se sienten muy largas y explica confuso, la verdad con solo ponerle atención a los ejemplos basta para entender los ejercicios del exámen'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '850356167722d0c662e847666b61df23dfde2656bbd01981a8065021019ece05'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Buena nota el profe, ayuda mucho en consulta, pero sus explicaciones en clases fueron muy confusas, presentaciones basadas en hojas con escritos hechos por una persona con pésima caligrafía. Califica suave. Ama a los estudiantes de materiales.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Pocos exámenes']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '765605ddcaceb7d3cbd498bf835fa6d59fd112c8e02ca8456b6cfbd977a04073'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Explica bien los temas del curso, la presentacion no ayuda mucho pero el libro suple muy bien su funcion. El examen tareas las hace muy faciles, iguales a lo visto en clase. Lo lleve en verano y recomendadisimo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2025-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'be9bc6939d434211062f6529f860b2cb7cb5cd7489e055a7f4b0b507cb9a1ef0'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Excelente profesor, los exámenes son ejercicios parecidos a las tareas, califica suave y es muy amable al responder consultas. Lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-13T00:00:00+00:00'::TIMESTAMPTZ, '00b33ab82fafb90414ccad45987786617d17c988d5531e501cafb9cfc8b55f3a'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'El profe tenía rato de no dar el curso, entonces al inicio se notaba un poco pérdido, pero luego se acomodó. Los examenes y tareas eran parecidos a los ejercicios de la clase y brindó apoyo en estos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, '218d0adb72588fda22aee7c1562d76c52952457463093c0ef061bbb678c6e637'::TEXT, ARRAY[2763]::BIGINT[]),
    (88::BIGINT, 'El profe se esfuerza para que todos entiendan. Los ejercicios de los examenes son parecidos a las prácticas y tareas. Le gusta que el estudiantes corroboren los ejercicios de la clase, lo que ayuda para prácticar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '8a0bdb3a8cf249eac97fd653d82dabd4f6871d1f5a746e98c168839c201f39e5'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Buena nota, examenes de nivel normal, deja que lleves formulario propio y él pone uno en el examen, las tareas te permiten repasar para el examen y aprender matlab. Siempre anda bien vestido y es puntual. Habla con acento cool'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '4475e43ce2d5c86749b023dbb213bb2a4723bad979f03105cd581bd2443a754a'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Muy bueno explicando, da buenas retroalimentaciones y lo que explica es lo que sale en el examen y trabajos. Siempre atento a alguna duda y es muy amable para aclararla.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, '713637d49af5da8e0c7798013e3f3b3730a19b0c75e6d3b1aa32a8989b2a57b6'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Es un profesor excepcional!! Tiene un amplio dominio de la materia, y las clases son muy bien explicadas con un buen balance de teoría y ejemplos. Para dudas, es muy pendiente y accesible. Los ejercicios que se cubren en clase son muy buenos para pruebas. Un súper profe!! 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-01-18T00:00:00+00:00'::TIMESTAMPTZ, '4e84de6a43c8385f30a6632758abbe28f8acbf34e248724979aa23a64b3548de'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Si no quiere programar, matricule con él. Explica todo con MUCHO detalle por lo que las clases son muy largas. TODO es a mano pero muy sencillo, los ejercicios del examen son iguales a los de la tareas. Si practica haciendo las tareas se pasa súper fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'b5e96df32170d441c5031b77e09e5d516ff48bb0ca6514d49877bf6b38fa9302'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'En general el profe es bastante bueno. Las clases son largas y explica a fondo como sale una formula y luego resuelve un ejercicio. Todas las tareas y examenes son grupales y hechos a mano. Se aprende lo basico de programacion en Matlab porque la mayoria de las evaluaciones son hechas a mano.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c69f03b31d6f20d5bed779f067b08488af8dbe52ac8dd7927eeb1bc0cd4d205d'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Todo se basa en el proyecto, solo hay que estudiar para el primer examen, pero eso con hacer la primera tarea sale. Todo se hace en grupos.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b6c5e1a381e2973658da5cc3ab8fbb6fc388d2b82a464dd49c0e6feeeb73083b'::TEXT, ARRAY[2767]::BIGINT[]),
    (88::BIGINT, 'Bastante bueno, se pasa sencillo y con la explicación que muestra en clase y los pdf que envía es preparación suficiente para el examen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, '5bd6026fb639fb9b786f480b71e9c1482ea87768630bd415f3592f31b03f2471'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'buen profe, se le va mucho explicando de dónde sale cada fórmula, pero siempre hace ejercicios de práctica. Las tareas son de acuerdo a lo visto en clase y casi todo se hace grupal.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '2035b5dc7ddb65cb069f03b54e72ea44e2a6aeefe4eb89d12abf42f9c4206002'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Demasiada hablada para ver cómo se llegó a una fórmula, vea así como los ejemplos cuando lo explica y ya, no es dificil y haga todo en grupo para mayor facilidad...yo pasé todo el curso solo jaja'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-11-11T00:00:00+00:00'::TIMESTAMPTZ, '4e4a92ab3eb4ca48818016ce3ee7f777420860b2d4eb5b7d998277de795af935'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Las clases son bastante largas y aburridas ya que el profe explica con detalle cada fórmula, fuera de eso las tareas y exámenes son en grupo y los ejercicios que pone son muy similares a los que realiza en clase, además que las tareas programadas las basa en el libro de texto del curso.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'b201f8b21d72dd06563b62094ffa17d09fbcceda44767b2451e5fe5b0aef64bd'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Es buen profesor, aunque es difícil entenderle ya que su español no es el mejor, las clases son largas y aburridas. Califica bien y hace que el curso sea de una dificultad media.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '23335ca3f197e91a6ee724df1eece56c7aa937ded374d8b71e8882bb0c07ffde'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Las clases son largas, y a veces cuesta estar de lleno en la clase, pero explica muy bien. Los exámenes y las tareas son de dificultad media o baja, ya que toma ejercicios del libro. En general, un buen profesor, que además no hace pesado el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-02-25T00:00:00+00:00'::TIMESTAMPTZ, 'e610e2321ec2e212a95826d6213eb8d7030aed05794365b95860d177e2b7a6a6'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Las clases pueden llegar a ser aburridas y las presentaciones son algo desordenadas, no vale tanto la pena conectarse. Pero en general él intenta que la gente entienda la materia y ayuda bastante. Las tareas y los exámenes no son tan difíciles.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'c4744de5c6b14b9f65fcf4f1888b56c315e2fdf09a2a7ec51bc60be8bf6901cd'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'El profe es muy pura vida y califica suave. Si ud le pide ayuda él de fijo va a hacer todo lo posible para que ud entienda la materia. Explica muy mal, las presentaciones son terribles. Conectarse a clases es una perdida de tiempo.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '214dbf80f6e26a69c228d60399a9d172fd42aa3a4db502d68a214feb158851f4'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'La clase podría durar la mitad del tiempo y usa material un poco ilegible, pero el curso es muy llevadero y la dificultad adecuada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '485af370022d02d1877cbdc9434dd87dade1f979b463dee983f7d62333f6d2fc'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Las clases son largas, pero si no le entiende busque en youtube los videos de Rebeca y así se ayuda con los ejercicios que el profe hace(los cuales son similares a examen). Es buen profe.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '51d0254ff76a640ab3ab80905b7a56960d31b09136f27cdcf1ff3395d8b6a5cf'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Recomendado, en virtual, explicó bien, lo más importante es hacer los ejemplos y ejercicios que él propone, porque tienen dificultad de examen. Es comprensible con la situación actual y entregables, en general buen profe'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '535f912d3cdcd3a80944c33e0ec86371e1fd74c1c7139fd6e1567a998b606f73'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Es buen profesor, pero un poco desconsiderado a la hora de hacer los exámenes virtuales, muy largos y no da el tiempo suficiente. Hay que ponerle mucha atención a la hora de hacer los ejemplos, es donde más se entiende.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2020-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'beae793c2701e2ee12954e552c29b05aadb8d388784a0282e9ae81793fb3b0c9'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Domina muy bien la materia y sus evaluaciones son coherentes con lo que enseña. En verano comparte el curso con Adrian Quesada'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'f66b8f19232d760ff78238790e6d4f858dd5c4c2ba2f5f08ff5060ced840ab59'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2019-02-13T00:00:00+00:00'::TIMESTAMPTZ, 'f1a7ba14b4b48b6c959786583a0e44289cda5781cffdf24a41a996ece628745d'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Mejor no matricule con él'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2019-01-01T00:00:00+00:00'::TIMESTAMPTZ, 'c63360c4b52349b85328812a6a283931e928811140c7658090bf1690d16dc6aa'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Hay mejores profes para el curso'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2018-12-12T00:00:00+00:00'::TIMESTAMPTZ, '0f8dfe80faa08f707d5be0b483e5fd29860baef66683c46bba0df56b6b11fa1c'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2018-08-13T00:00:00+00:00'::TIMESTAMPTZ, '36ab7b005c50a76250754a33a58ae9a0d4d9880ebb476837e41dad54416521e3'::TEXT, ARRAY[949]::BIGINT[]),
    (88::BIGINT, 'Se disfruta escuchar a este profesor hablar sobre ingeniería.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1a357d990bbba3507ade0a5c01ed567b687092fa6428e9087509d6ae3efb562c'::TEXT, ARRAY[2767, 2764]::BIGINT[]),
    (88::BIGINT, 'Muy justo, pero explica lentísimo'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '82b92ddc5a52b88dfbc6a6ab719370e5051f810142c5461880c6b7dda5616f32'::TEXT, ARRAY[2764]::BIGINT[]),
    (88::BIGINT, 'Un profesor muy recto, que califica justo y explica bien. Hace el curso facil, tal vez si espera aprender bastante sea mejor otra opcion'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '965f81acb8fc972f5be1658fcc7be6a9463a580b75efae6b7162985211b1d8c8'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'El mejor profesor que he tenido en la universidad. Tiene un conocimiento amplio sobre todas las bases de la ingeniería y es super comprometido con sus estudiantes'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'badcb6ed8a6a836f88ff63c0b47ce2220b9a702ff3bbefbdc0f5fe8874ca5592'::TEXT, ARRAY[2767]::BIGINT[]),
    (88::BIGINT, 'Buen profe, se atrasa un poco en el plan y dura mucho explicando un tema, pero ninguno como él para ese curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'fa71fe03fd76b3126134949ea18e0a7b512ebaeb45efb0a1dcd9eaaa66271ebd'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Uno de los mejores profesores que he tenido, es paciente con los estudiantes, le interesa el aprendizaje de los mismos, sabe mucho y califica justo. Si usted falla en algo, el profesor se lo indica para que usted lo corrija.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'c0065a6cb39a49e81ec6f04933fa497c2b4136f54593be87fa0a1a484ecd8df3'::TEXT, ARRAY[2743]::BIGINT[]),
    (88::BIGINT, 'De los mejores profesores. Totalmente recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '2e08c5e821d69fb573a4bd3ad46426fc2cd51f7471082f3bb338e6d3c6e8c547'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'b79bf5733c8165a6b04198941775ca725a20eded50924f967e1b11c169fdf6b7'::TEXT, ARRAY[2767, 3866]::BIGINT[]),
    (88::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '1888fa4041f01b98fa1c669df876c9c012e74ac4eb623ed3286a15abfbde58c6'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Buena nota, explica bien, ayuda demasiado a la hora de calificar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '26cc9bbb4b2b150c2b05861150e102f22bb4a3dd654adc2727c13fa7b374a939'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '7d17321bae2ab02175f72360e50eb0c665e1087d7cdb0df2d152b813b0d044cc'::TEXT, ARRAY[968]::BIGINT[]),
    (88::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '4646b814590bdbbbb4611115c1fa3965a79b38393c01fdba1db6bd6c507b645c'::TEXT, ARRAY[968]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
